/** Same as the site's t(key, vars): language, then de, then en, then the key itself. */
export function st(key, vars = {}) {
  const group = SITE_TEXT[key] || {};
  const template = group[lang()] || group.de || group.en || key;
  return String(template).replace(/\{(\w+)\}/g, (_, name) => (vars[name] ?? ''));
}
